package com.jnapanam.sportszone.content.service;
import com.jnapanam.sportszone.catalog.model.*;import com.jnapanam.sportszone.catalog.repository.*;import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.content.dto.*;import com.jnapanam.sportszone.content.model.*;import com.jnapanam.sportszone.content.repository.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ContentService{private final PublicEventRepository events;private final AnnouncementRepository announcements;private final GalleryItemRepository gallery;private final ContentPageRepository pages;private final ContactInquiryRepository inquiries;private final SportRepository sports;private final FacilityRepository facilities;public ContentService(PublicEventRepository e,AnnouncementRepository a,GalleryItemRepository g,ContentPageRepository p,ContactInquiryRepository i,SportRepository s,FacilityRepository f){events=e;announcements=a;gallery=g;pages=p;inquiries=i;sports=s;facilities=f;}
 @Transactional(readOnly=true)public List<EventResponse>publicEvents(){return events.findByStatusAndEndsAtAfterOrderByDisplayOrderAscStartsAtAsc(ContentStatus.PUBLISHED,Instant.now()).stream().map(EventResponse::from).toList();}@Transactional(readOnly=true)public List<EventResponse>allEvents(){return events.findAllByOrderByStartsAtDesc().stream().map(EventResponse::from).toList();}
 @Transactional public EventResponse createEvent(EventRequest r){if(events.existsBySlugIgnoreCase(r.slug()))throw new ConflictException("Event slug already exists");validateEvent(r);return EventResponse.from(events.save(new PublicEvent(r.slug(),r.title(),r.description(),r.eventType(),sport(r.sportCode()),facility(r.facilityId()),r.startsAt(),r.endsAt(),r.registrationUrl(),r.imageUrl(),r.capacity(),r.featured(),r.displayOrder())));}
 @Transactional public EventResponse updateEvent(UUID id,EventRequest r){PublicEvent e=events.findById(id).orElseThrow(()->new NotFoundException("Event not found"));if(!e.getSlug().equalsIgnoreCase(r.slug()))throw new BadRequestException("Event slug cannot be changed");validateEvent(r);e.update(r.title(),r.description(),r.eventType(),sport(r.sportCode()),facility(r.facilityId()),r.startsAt(),r.endsAt(),r.registrationUrl(),r.imageUrl(),r.capacity(),r.featured(),r.displayOrder());return EventResponse.from(e);}@Transactional public EventResponse eventStatus(UUID id,ContentStatusRequest r){PublicEvent e=events.findById(id).orElseThrow(()->new NotFoundException("Event not found"));e.status(r.status());return EventResponse.from(e);}
 @Transactional(readOnly=true)public List<AnnouncementResponse>publicAnnouncements(){return announcements.active(ContentStatus.PUBLISHED,Instant.now()).stream().map(AnnouncementResponse::from).toList();}@Transactional(readOnly=true)public List<AnnouncementResponse>allAnnouncements(){return announcements.findAllByOrderByCreatedAtDesc().stream().map(AnnouncementResponse::from).toList();}@Transactional public AnnouncementResponse createAnnouncement(AnnouncementRequest r){if(r.publishUntil()!=null&&r.publishUntil().isBefore(r.publishFrom()))throw new BadRequestException("Announcement dates are invalid");return AnnouncementResponse.from(announcements.save(new Announcement(r.title(),r.body(),r.priority(),r.publishFrom(),r.publishUntil())));}@Transactional public AnnouncementResponse announcementStatus(UUID id,ContentStatusRequest r){Announcement a=announcements.findById(id).orElseThrow(()->new NotFoundException("Announcement not found"));a.status(r.status());return AnnouncementResponse.from(a);}
 @Transactional(readOnly=true)public List<GalleryResponse>publicGallery(){return gallery.findByPublishedTrueOrderByDisplayOrderAscCreatedAtDesc().stream().map(GalleryResponse::from).toList();}@Transactional(readOnly=true)public List<GalleryResponse>allGallery(){return gallery.findAllByOrderByDisplayOrderAscCreatedAtDesc().stream().map(GalleryResponse::from).toList();}@Transactional public GalleryResponse createGallery(GalleryRequest r){return GalleryResponse.from(gallery.save(new GalleryItem(r.title(),r.mediaType(),r.mediaUrl(),r.thumbnailUrl(),r.altText(),sport(r.sportCode()),r.published(),r.displayOrder())));}
 @Transactional(readOnly=true)public PageResponse publicPage(String slug){return PageResponse.from(pages.findBySlugIgnoreCaseAndStatus(slug,ContentStatus.PUBLISHED).orElseThrow(()->new NotFoundException("Page not found")));}@Transactional(readOnly=true)public List<PageResponse>allPages(){return pages.findAllByOrderBySlugAsc().stream().map(PageResponse::from).toList();}@Transactional public PageResponse savePage(PageRequest r){ContentPage p=pages.findBySlugIgnoreCase(r.slug()).orElseGet(()->new ContentPage(r.slug(),r.title(),r.summary(),r.body()));p.update(r.title(),r.summary(),r.body(),r.status());return PageResponse.from(pages.save(p));}
 @Transactional public ContactResponse contact(ContactRequest r){return ContactResponse.from(inquiries.save(new ContactInquiry(r.name(),r.email(),r.mobile(),r.subject(),r.message())));}@Transactional(readOnly=true)public List<ContactResponse>inquiries(InquiryStatus s){List<ContactInquiry>v=s==null?inquiries.findAllByOrderByCreatedAtDesc():inquiries.findByStatusOrderByCreatedAtDesc(s);return v.stream().map(ContactResponse::from).toList();}@Transactional public ContactResponse inquiryStatus(UUID id,InquiryStatusRequest r){ContactInquiry c=inquiries.findById(id).orElseThrow(()->new NotFoundException("Inquiry not found"));c.status(r.status(),r.adminNote());return ContactResponse.from(c);}
 private Sport sport(String code){return code==null||code.isBlank()?null:sports.findByCodeIgnoreCase(code).orElseThrow(()->new NotFoundException("Sport not found"));}private Facility facility(UUID id){return id==null?null:facilities.findById(id).orElseThrow(()->new NotFoundException("Facility not found"));}private static void validateEvent(EventRequest r){if(!r.endsAt().isAfter(r.startsAt()))throw new BadRequestException("Event end must be after start");}}
